Let’s Add Other Operations
RegisterHandle genExpr( node ) {
RegisterHandle result, t1, t2;
switch( type of node ) {
//...
case TIMES: t1 = genExpr( node.left_child );
t2 = genExpr( node.right_child );
result = new_reg_name();
emit( mult, t1, t2, =>, result );
break;
case MINUS: t1 = genExpr( node.left_child );
t2 = genExpr( node.right_child );
result = new_reg_name();
emit( sub, t1, t2, =>, result );
break;
}
return result;
}
